<script>
 import {onMount,onDestroy,untrack} from 'svelte';
 let {source,recordings=[],request,selectedMomentId='',externalMomentSelected=false,onMomentChange=()=>{},onUseMoment=()=>{},onSelection=()=>{},onDirtyChange=()=>{},onSaved=()=>{}}=$props();
 let result=$state(null),startWindow=$state(0),endWindow=$state(60),selectedId=$state(''),start=$state(0),end=$state(15),context=$state(''),recordingId=$state(''),recordingFit=$state(''),base=$state(''),loadedRevision=$state(0),requiresSave=$state(false),busy=$state(false),error=$state(''),notice=$state(''),pending=$state(null),unknown=$state(false);
 let alive=true;const analysis=$derived(result?.analyses?.find(a=>a.moments?.some(m=>m.id===selectedMomentId))||result?.analysis),moments=$derived(analysis?.moments||[]),selected=$derived(moments.find(m=>m.id===selectedId));
 const values=()=>({id:selectedId,startSeconds:Number(start),endSeconds:Number(end),context,recordingId:recordingId||null,recordingFit});
 const dirty=$derived(Boolean(pending)||Boolean(selectedId&&(requiresSave||base!==JSON.stringify(values()))));
 $effect(()=>onDirtyChange(dirty));
 $effect(()=>onSelection(selected?.savedAt&&!dirty?$state.snapshot(selected):null,analysis?.id||''));
 function adopt(moment,revision=analysis?.revision||0){selectedId=moment?.id||'';start=moment?.startSeconds??0;end=moment?.endSeconds??15;context=moment?.context||'';recordingId=moment?.recordingId||'';recordingFit=moment?.recordingFit||'';loadedRevision=revision;requiresSave=false;base=JSON.stringify(values());}
 $effect(()=>{selectedMomentId;analysis?.id;analysis?.revision;untrack(()=>{if(!dirty&&!busy){const next=selectedMomentId?moments.find(m=>m.id===selectedMomentId):moments[0];adopt(next);}});});
 async function load(){if(busy)return;busy=true;error='';try{const next=await request('/inbox/analysis?sourceId='+encodeURIComponent(source.id));if(alive)result=next;}catch(e){if(alive)error=e.message;}finally{if(alive)busy=false;}}
 function choose(id){if(dirty||busy)return;adopt(moments.find(m=>m.id===id));onMomentChange(id);notice='';}
 function analyze(){if(busy||dirty)return;if(!Number.isFinite(Number(startWindow))||!Number.isFinite(Number(endWindow))||Number(startWindow)<0||Number(endWindow)<=Number(startWindow)||Number(endWindow)>86400||Number(endWindow)-Number(startWindow)>300){error='Choose a video window of up to five minutes, with its end after its start.';return;}pending={path:'/inbox/analysis',body:{sourceId:source.id,idempotencyKey:crypto.randomUUID(),expectedSourceRevision:source.revision,window:{startSeconds:Number(startWindow),endSeconds:Number(endWindow)}}};void submit();}
 function save(){if(busy||pending||!selected)return;if(!Number.isFinite(Number(start))||!Number.isFinite(Number(end))||Number(start)<0||Number(end)<=Number(start)||Number(end)-Number(start)>30){error='Choose a proposed moment of up to 30 seconds.';return;}pending={path:'/inbox/analysis/moments',body:{sourceId:source.id,analysisId:analysis.id,expectedRevision:loadedRevision,idempotencyKey:crypto.randomUUID(),moment:values()}};void submit();}
 async function submit(){if(!pending||busy)return;busy=true;error='';notice='';try{const kind=pending.path.endsWith('/moments')?'moment':'analysis';const next=await request(pending.path,{method:'POST',body:JSON.stringify($state.snapshot(pending.body))});if(!alive)return;result=next;pending=null;unknown=false;if(kind==='moment'){adopt(next.analysis.moments.find(m=>m.id===selectedId),next.analysis.revision);onMomentChange(selectedId);notice='Proposed moment saved';}else{adopt(next.analysis?.moments?.[0],next.analysis?.revision||0);onMomentChange(selectedId||'');notice=next.analysis?.status==='ready'&&next.analysis.moments.length?'Analysis ready. Review the proposed moments.':next.analysis?.status==='running'?'Analysis requested. Refresh its status.':'';}try{await onSaved();}catch{error='Your analysis is retained. Reload current references before the next workspace save.';}}catch(e){if(!alive)return;error=e.status===409?'A newer analysis is saved. Your working proposal is retained. Refresh and compare before saving.':e.message;unknown=!(Number.isInteger(e.status)&&e.status>=400&&e.status<500);if(!unknown)pending=null;}finally{if(alive)busy=false;}}
 function sourceAtTime(){const url=new URL(source.sourceUrl);url.searchParams.set('t',Math.floor(Math.max(0,Number(start)||0))+'s');return url.href;}
 function keep(){if(!analysis)return;loadedRevision=analysis.revision;requiresSave=true;notice='Your proposal is retained on the current analysis. Save it before using it.';}
 function discard(){if(busy||pending)return;adopt(selected);error='';notice='';}
 onMount(()=>{void load();});onDestroy(()=>{alive=false;onDirtyChange(false);onSelection(null,'');});
</script>
<section class="preprocess" aria-label="Analyze source video">
 <h4>Find a moment in this source</h4><p>Analyze the YouTube link before supplying media. Suggested times and song fit are approximate proposals to review.</p>
 {#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if busy}<p role="status">{pending?'Working on this source…':'Loading analysis…'}</p>{/if}
 {#if unknown}<button disabled={busy} onclick={submit}>Check same analysis request</button><p>The reply was interrupted. This checks the retained request without asking for another analysis.</p>{/if}
 <fieldset disabled={busy||dirty||unknown}><legend>Video window to inspect</legend><div class="times"><label>Analyze from (seconds)<input type="number" min="0" max="86400" step="1" bind:value={startWindow}/></label><label>Analyze to (seconds)<input type="number" min="1" max="86400" step="1" bind:value={endWindow}/></label></div><button disabled={!result?.configured||analysis?.status==='running'} onclick={analyze}>{analysis?.status==='unknown'?'Start a new analysis':'Analyze YouTube source'}</button></fieldset>
 {#if result&&!result.configured}<p>Video analysis is not configured. Existing saved moments remain available.</p>{/if}
 {#if analysis}<p class="status">{analysis.status==='ready'?'Proposed moments':analysis.status==='running'?'Analysis in progress':analysis.status==='failed'?'Analysis could not complete':'Analysis outcome needs checking'} · {analysis.createdAt}</p>{#if analysis.status==='ready'&&!moments.length}<p>No suitable moments found in this window. Try another time range.</p>{/if}{#if analysis.error}<p role="alert">{analysis.error}</p>{/if}<button disabled={busy||unknown} onclick={load}>Refresh analysis</button>{/if}
 {#if selectedMomentId&&!externalMomentSelected&&analysis&&!selected}<p>The linked moment is not available in this analysis. Choose another saved proposal.</p>{/if}
 {#if moments.length}<label>Proposed moment<select value={selectedId} disabled={busy||dirty} onchange={e=>choose(e.currentTarget.value)}><option value="" disabled>Choose a moment</option>{#each moments as moment(moment.id)}<option value={moment.id}>{moment.startSeconds}–{moment.endSeconds}s{moment.savedAt?' · saved':''}</option>{/each}</select></label>
 {#if selected}<fieldset disabled={busy||unknown}><legend>Review the proposed moment</legend><a href={sourceAtTime()} target="_blank" rel="noopener noreferrer">Open source at proposed time ↗</a><div class="times"><label>Proposed in (seconds)<input type="number" min="0" step="0.1" bind:value={start}/></label><label>Proposed out (seconds)<input type="number" min="0" step="0.1" bind:value={end}/></label></div><label>Moment context<textarea rows="3" maxlength="2000" bind:value={context}></textarea></label><label>Proposed recording<select bind:value={recordingId}><option value="">No recording selected</option>{#each recordings as recording(recording.id)}<option value={recording.id}>{recording.title}</option>{/each}</select></label><label>Recording fit<textarea rows="2" maxlength="2000" bind:value={recordingFit}></textarea></label>
 {#if analysis.revision!==loadedRevision}<p>A newer analysis is available. Your working values are retained.</p><button onclick={keep}>Keep my proposal on the current revision</button>{/if}
 <button disabled={!context.trim()||analysis.revision!==loadedRevision||Boolean(pending)} onclick={save}>Save proposed moment</button><button disabled={!selected?.savedAt||dirty||Boolean(pending)} onclick={()=>onUseMoment($state.snapshot(selected))}>Use saved moment in clip settings</button>{#if dirty&&!pending}<button onclick={discard}>Discard moment changes</button>{/if}</fieldset>
 {#if selected?.savedAt&&!dirty}<p>Saved proposal · {selected.savedAt}. Media and permission are still required for a later render.</p>{/if}{/if}{/if}
</section>
<style>.preprocess{border-block:1px solid #dedfd8;padding:16px 0;margin:18px 0}.preprocess h4{font-size:17px;margin:0 0 8px}.preprocess p{font-size:13px;line-height:1.5}.preprocess fieldset{border:0;padding:0;margin:12px 0}.preprocess legend{font-weight:600;font-size:13px}.preprocess label{display:block;font-size:13px;margin:10px 0}.preprocess input,.preprocess select,.preprocess textarea{display:block;width:100%;margin-top:5px}.times{display:flex;gap:12px}.times label{flex:1;min-width:0}.preprocess button{margin:4px 8px 4px 0}.status{color:#596a51}</style>
